<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class InstallationKey {
 private const SETTING='upgrade_installation_key';
 private static function actor(\PDO $p,int $u):void {if(!Authorization::super($p,$u))throw new \RuntimeException('Super Admin aktif diperlukan.');}
 private static function record(\PDO $p):?array {$raw=Database::query($p,'SELECT setting_value FROM system_settings WHERE setting_key=?',[self::SETTING])->fetchColumn();if($raw===false)return null;$r=json_decode((string)$raw,true,512,JSON_THROW_ON_ERROR);if(!is_array($r)||!is_string($r['hash']??null)||!preg_match('/\A[a-f0-9]{32}\z/',$r['epoch']??'')||password_get_info($r['hash'])['algoName']==='unknown')throw new \RuntimeException('Installation Key metadata tidak sah.');return $r;}
 public static function configured(\PDO $p):bool {return self::record($p)!==null;}
 private static function format(string $k,string $confirm):void {if(!preg_match('/\A[0-9]{12}\z/D',$k)||$k!==$confirm)throw new \InvalidArgumentException('Installation Key mesti tepat 12 digit dan pengesahan mesti sepadan.');}
 private static function directory():string {$d=APP_ROOT.'/storage/upgrades';if(UpgradePackage::symlink($d)||!is_dir($d)||!is_writable($d))throw new \RuntimeException('Private key storage tidak tersedia.');return $d;}
 private static function locked(callable $f):mixed {$path=self::directory().'/key-security.lock';if(UpgradePackage::symlink($path))throw new \RuntimeException('Key lock tidak selamat.');$h=fopen($path,'c+');if(!$h||!flock($h,LOCK_EX))throw new \RuntimeException('Key security lock tidak tersedia.');chmod($path,0600);try{return $f();}finally{flock($h,LOCK_UN);fclose($h);}}
 private static function password(\PDO $p,int $u,string $password):void {(new LiveUpgradeManager($p,$u,APP_ROOT))->confirm($password);}
 private static function revision(\PDO $p,int $u):int {return (int)Database::query($p,'SELECT credential_revision FROM users WHERE id=? AND is_active=1',[$u])->fetchColumn();}
 private static function persist(\PDO $p,int $u,string $k,string $event,string $reason):void {Core::tx($p,function()use($p,$u,$k,$event,$reason){$r=['hash'=>password_hash($k,PASSWORD_DEFAULT),'epoch'=>bin2hex(random_bytes(16))];Versions::set($p,self::SETTING,json_encode($r,JSON_THROW_ON_ERROR));Audit::record($p,$event,$u,null,'installation_key','core',$reason);});unset($_SESSION['upgrade_key_auth'],$_SESSION['upgrade_once']);}
 public static function setup(\PDO $p,int $u,string $key,string $confirm,string $password):void {self::actor($p,$u);self::format($key,$confirm);self::password($p,$u,$password);self::locked(function()use($p,$u,$key){if(self::record($p)!==null)throw new \RuntimeException('Installation Key sudah ditetapkan.');self::persist($p,$u,$key,'upgrade.key_created','First-time setup');});}
 private static function verifyLocked(\PDO $p,int $u,string $key):array {
  $file=self::directory().'/key-attempts.json';if(UpgradePackage::symlink($file))throw new \RuntimeException('Throttle path tidak selamat.');$rows=is_file($file)?json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR):[];if(!is_array($rows))throw new \RuntimeException('Throttle tidak sah.');$rows=array_values(array_filter($rows,static fn($r)=>is_array($r)&&is_int($r['at']??null)&&$r['at']>time()-900));$own=count(array_filter($rows,static fn($r)=>($r['actor']??null)===$u));if($own>=5||count($rows)>=10){Audit::record($p,'upgrade.key_rate_limited',$u);throw new \RuntimeException('Terlalu banyak percubaan. Cuba selepas 15 minit.');}
  $r=self::record($p);if(!$r||!preg_match('/\A[0-9]{12}\z/D',$key)||!password_verify($key,$r['hash'])){$rows[]=['actor'=>$u,'at'=>time(),'ip_hash'=>hash('sha256',$_SERVER['REMOTE_ADDR']??'cli')];Support::secureWrite($file,json_encode($rows,JSON_THROW_ON_ERROR));Audit::record($p,'upgrade.key_rejected',$u);throw new \RuntimeException('Installation Key tidak sah.');}Support::secureWrite($file,json_encode($rows,JSON_THROW_ON_ERROR));return $r;
 }
 public static function verify(\PDO $p,int $u,string $key):void {self::actor($p,$u);self::locked(function()use($p,$u,$key){$r=self::verifyLocked($p,$u,$key);$_SESSION['upgrade_key_auth']=['actor'=>$u,'epoch'=>$r['epoch'],'credential_revision'=>self::revision($p,$u),'expires'=>time()+600];Audit::record($p,'upgrade.key_verified',$u);});}
 public static function authorized(\PDO $p,int $u):bool {self::actor($p,$u);$r=self::record($p);$a=$_SESSION['upgrade_key_auth']??null;return $r&&is_array($a)&&($a['actor']??null)===$u&&($a['epoch']??null)===$r['epoch']&&($a['credential_revision']??null)===self::revision($p,$u)&&is_int($a['expires']??null)&&$a['expires']>=time();}
 public static function requireAuthorization(\PDO $p,int $u):void {if(!self::authorized($p,$u))throw new \RuntimeException('Sahkan Installation Key semula; kebenaran sementara tamat atau berubah.');}
 public static function rotate(\PDO $p,int $u,string $old,string $key,string $confirm,string $password):void {self::actor($p,$u);self::format($key,$confirm);self::password($p,$u,$password);self::locked(function()use($p,$u,$old,$key){self::verifyLocked($p,$u,$old);self::persist($p,$u,$key,'upgrade.key_rotated','Super Admin rotation');});}
 public static function recovery(\PDO $p,int $u,string $password):string {if(PHP_SAPI!=='cli')throw new \RuntimeException('Recovery memerlukan pentadbiran Terminal.');self::actor($p,$u);self::password($p,$u,$password);return self::locked(function()use($p,$u){$r=self::record($p);if(!$r)throw new \RuntimeException('Installation Key belum ditetapkan.');$token=bin2hex(random_bytes(32));$path=self::directory().'/key-recovery.json';if(UpgradePackage::symlink($path))throw new \RuntimeException('Recovery path tidak selamat.');Support::secureWrite($path,json_encode(['hash'=>hash('sha256',$token),'actor'=>$u,'epoch'=>$r['epoch'],'expires'=>time()+900],JSON_THROW_ON_ERROR));Audit::record($p,'upgrade.key_recovery_issued',$u);return $token;});}
 public static function reset(\PDO $p,int $u,string $token,string $key,string $confirm,string $password,string $reason):void {self::actor($p,$u);self::format($key,$confirm);if(trim($reason)===''||strlen($reason)>500)throw new \InvalidArgumentException('Sebab recovery diperlukan.');self::password($p,$u,$password);self::locked(function()use($p,$u,$token,$key,$reason){$path=self::directory().'/key-recovery.json';if(UpgradePackage::symlink($path)||!is_file($path))throw new \RuntimeException('Recovery authorization tiada.');$a=json_decode(file_get_contents($path),true,512,JSON_THROW_ON_ERROR);$r=self::record($p);if(!preg_match('/\A[a-f0-9]{64}\z/',$token)||!is_array($a)||!$r||($a['actor']??null)!==$u||($a['epoch']??null)!==$r['epoch']||($a['expires']??0)<time()||!hash_equals((string)($a['hash']??''),hash('sha256',$token)))throw new \RuntimeException('Recovery authorization tidak sah atau tamat.');self::persist($p,$u,$key,'upgrade.key_reset',$reason);Support::secureWrite($path,json_encode(['used'=>true,'expires'=>0],JSON_THROW_ON_ERROR));});}
}
